    const coachMurmurVol = (cameraMode === 4) ? (0.013 + 0.004 * Math.sin(now * 1.3)) : 0.0;
    const rainVol = (isStorm && !inTunnel) ? (isInteriorView ? 0.024 : 0.085) : 0.0;
    this.highwayTrafficGain.gain.setTargetAtTime(hwyVol, now, 0.18);
    this.ruralBreezeGain.gain.setTargetAtTime(breezeVol, now, 0.20);
    this.cicadaGain.gain.setTargetAtTime(cicadaVol, now, 0.20);
    this.cricketGain.gain.setTargetAtTime(cricketVol, now, 0.035);
    this.coachMurmurGain.gain.setTargetAtTime(coachMurmurVol, now, 0.18);
    this.rainFilter.frequency.setTargetAtTime(isInteriorView ? 780 : 2150, now, 0.12);
