    armsGroup.add(lowerArm, upperArmL, upperArmR);
    const panHead = new THREE.Group();
    panHead.position.set(0, 1.28, 0);
    const stripF = new THREE.Mesh(new THREE.BoxGeometry(1.68, 0.045, 0.08), frameMat);
