    const fHead = EndlessWorldMathematics.getTrackFrame(leadS, 0, originS, _scanFrame);
    let minLim = this.getWeatherRestrictedTrackLimitKmh(fHead, maxTrainKmh);
    const tailS = THREE.MathUtils.clamp(leadS - this.travelDir * trainLenM, 0, maxRoute);
    const midS = (leadS + tailS) * 0.5;
    const fMid = EndlessWorldMathematics.getTrackFrame(midS, 0, originS, _scanFrame);
    const midLim = this.getWeatherRestrictedTrackLimitKmh(fMid, maxTrainKmh);
    if (midLim < minLim) minLim = midLim;
    const fTail = EndlessWorldMathematics.getTrackFrame(tailS, 0, originS, _scanFrame);
    const tailLim = this.getWeatherRestrictedTrackLimitKmh(fTail, maxTrainKmh);
    if (tailLim < minLim) minLim = tailLim;
