      const aeroN = aeroC * absV * absV;
      const absCurv = Math.abs(frame.curvature);
      const curveDragN = absCurv > 0.00004 ? (massTons * 9.81 * (absCurv * 600.0) * 0.001) : 0.0;
      const dragN = (rollingN + aeroN + curveDragN) * (this.speedMps >= 0 ? 1 : -1);
