        if (this.keys['ArrowUp']) this.coachWalkZ = Math.max(-11.35, this.coachWalkZ - aisleStep);
        if (this.keys['ArrowDown']) this.coachWalkZ = Math.min(11.35, this.coachWalkZ + aisleStep);
        const baseAisleX = cClass === 'BUSINESS' ? 0.0 : (cClass === 'FIRST' ? -0.22 : -0.15);
        const bordesBlend = THREE.MathUtils.clamp((Math.abs(this.coachWalkZ) - 8.8) / 0.85, 0.0, 1.0);
        const aisleX = THREE.MathUtils.lerp(baseAisleX, 0.0, bordesBlend);
