      const tHand = performance.now() * 0.001;
      const distNow = this.spotterPos.distanceTo(_locoPos);
      const buffetAmp = (distNow < 48.0 && Math.abs(this.speedMps) > 30.0)
        ? (1.0 - distNow / 48.0) * (Math.abs(this.speedMps) / 97.2) * 0.045
        : 0.0;
      const breathX = Math.sin(tHand * 1.45) * 0.008 + (Math.random() - 0.5) * buffetAmp;
