      const secondCar = this.train.vehicles[Math.min(1, this.train.vehicles.length - 1)] || loco;
      secondCar.bodyGroup.getWorldPosition(_tmpVecB);
      _tmpVecA.lerpVectors(_locoPos, _tmpVecB, 0.35);
      _tmpVecA.y += 2.35;
      _targetLookMat.lookAt(this.camera.position, _tmpVecA, this.camera.up);
      _lookQuat.setFromRotationMatrix(_targetLookMat);
